+/* Account delivery surface: existing personal artwork and governed method icons. */
+body[data-cx-surface="ACCOUNT"] .cx-account-hero{position:relative;isolation:isolate;overflow:hidden;min-height:23rem;padding:clamp(2rem,5vw,4.5rem);border-radius:1.5rem;background:#111b25;color:#f4eee0;justify-content:center;margin-top:1rem}
