+.cx-account-hero::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(12,20,29,.94),rgba(12,20,29,.73) 55%,rgba(12,20,29,.16))}
+body[data-cx-surface="ACCOUNT"] .cx-account-hero .cx-display{font-size:clamp(2.4rem,4.5vw,4.2rem);line-height:1.13;max-width:13ch;color:inherit;margin:.5rem 0}
