+.cx-account-shortcuts article{position:relative;padding:1.4rem;display:flex;flex-direction:column;align-items:flex-start;gap:.8rem}
+.cx-account-shortcuts h2{font-size:1.25rem!important;margin:0}.cx-account-shortcuts p{font-size:.9rem;margin:0}.cx-account-shortcuts .cx-button{margin-top:auto}
+.cx-account-shortcut-icon{width:2.5rem;height:2.5rem;object-fit:contain}
