+.cx-account-editor>summary{padding:1.2rem 1.4rem;font-weight:650;cursor:pointer}.cx-account-editor[open]>summary{border-bottom:1px solid var(--cx-color-border)}
+.cx-account-editor .cx-person-form,.cx-account-editor .cx-person-generate{border:0;margin:0;border-radius:0;background:transparent}
+.cx-account-reports{padding:1.5rem 0!important;border-top:1px solid var(--cx-color-border)}
+.cx-account-reports__heading{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:1.25rem}.cx-account-reports__heading h3{margin:0;font-size:1.5rem}
+.cx-account-report-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}
+.cx-account-report-card{display:flex;flex-direction:column;align-items:flex-start;gap:.8rem;padding:1.5rem;border:1px solid var(--cx-color-border);border-radius:1rem;background:linear-gradient(135deg,#fffefa,#f3ecdd)}
+.cx-account-report-card>img{width:3rem;height:3rem;object-fit:contain}.cx-account-report-card h4{font-size:1.15rem;line-height:1.5;margin:0}.cx-account-report-card p{font-size:.9rem;color:var(--cx-color-ink-muted);margin:0}.cx-account-report-card .cx-button{margin-top:auto}
+@media(max-width:48rem){body[data-cx-surface="ACCOUNT"] .cx-account-shortcuts{grid-template-columns:repeat(2,minmax(0,1fr))}.cx-account-report-grid{grid-template-columns:1fr}.cx-account-reports__heading{align-items:flex-start}.cx-account-hero{min-height:20rem!important}}
+@media(max-width:28rem){body[data-cx-surface="ACCOUNT"] .cx-account-shortcuts{grid-template-columns:1fr}.cx-account-reports__heading{flex-wrap:wrap}}
'@
$temp=Join-Path ([IO.Path]::GetTempPath()) ('phios-account-ui-'+[guid]::NewGuid().ToString()+'.patch')
try {
 [IO.File]::WriteAllText($temp,$patch+"`n",[Text.UTF8Encoding]::new($false))
 & git apply --check --whitespace=nowarn $temp
 if($LASTEXITCODE -ne 0){throw 'Patch preflight failed. No files changed.'}
 & git apply --whitespace=nowarn $temp
 if($LASTEXITCODE -ne 0){throw 'Patch apply failed.'}
 & node --check assets/customer-ui/js/surfaces/account-persons.js
 if($LASTEXITCODE -ne 0){throw 'JavaScript validation failed.'}
 Write-Host 'ACCOUNT UI PATCH APPLIED. No commit, push, deployment or provider request.'
} finally {if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp}}
